INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES (283, 'rank_math_description', 'সারসংক্ষেপ উত্তর: জাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) এবং মাধ্যমিক ও উচ্চশিক্ষা অধিদপ্তর (মাউশি)-এর সর্বশেষ প্রজ্ঞাপন অনুযায়ী ২০২৬ শিক্ষাবর্ষে ৬ষ্ঠ, ৭ম, ৮ম ও ৯ম শ্রেণির বার্ষিক পরীক্ষা মোট ১০০ নম্বরের ভিত্তিতে অনুষ্ঠিত হচ্ছে।');
